import React, {useState} from 'react';
import {Alert, Box, Button, Checkbox, Chip, Dialog, DialogActions, DialogContent, DialogTitle, FormControlLabel, MenuItem, Stack, Table, TableBody, TableCell, TableHead, TableRow, TextField, Typography} from '@mui/material';
import {Link, useSearchParams} from 'react-router-dom';
import {useAuth} from '../../auth/AuthContext';
import {MainDiv, PageHeader, PageTitle, Surface} from '../../ui/commonStyled/commonStyled';
import {CallView, TelephonySettings, useAssignCallMutation, useCallQuery, useCallsQuery, useOperationsUsersQuery, useSaveTelephonyMutation, useTelephonySettingsQuery} from './operationsApi';
import {date, ErrorBox, UserPicker} from './common';
const states:Record<string,string> = {ringing:'Звонит',answered:'Разговор',completed:'Завершён',missed:'Пропущен',failed:'Не состоялся'};
function CallEditor({data}:{data:CallView}) {
    const users = useOperationsUsersQuery(); const [orderId,setOrderId] = useState(data.call.orderId || 0); const [userId,setUserId] = useState(data.call.assignedUserId || 0);
    const [note,setNote] = useState(data.call.note); const [done,setDone] = useState(!!data.call.callbackCompletedAt); const [save,state] = useAssignCallMutation();
    return <Stack spacing={2}><Typography variant="h6">+{data.call.phone} · {states[data.call.state]}</Typography><Typography>{data.customers.map(c=>c.name).join(', ') || 'Клиент не найден в CRM'}</Typography>
        {data.orders.length>1 && <Alert severity="info">У клиента несколько заказов. Уточните тему разговора и выберите заказ.</Alert>}{data.customers.length>1 && <Alert severity="warning">Номер указан в нескольких карточках клиентов. Проверьте, кто звонит.</Alert>}
        {data.orders.length>=101 && <Alert severity="warning">Показан 101 последний заказ клиента. Автоматическая привязка отключена; проверьте нужный заказ в CRM.</Alert>}
        <ErrorBox error={state.error || users.error}/><TextField select label="Заказ, по которому звонят" value={orderId} onChange={e=>setOrderId(Number(e.target.value))}><MenuItem value={0}>Без привязки к заказу</MenuItem>{data.orders.map(o=><MenuItem key={o.id} value={o.id}>№{o.id} · {o.customerName} · {o.statusName}</MenuItem>)}</TextField>
        {orderId>0 && <Button component={Link} to={`/orderPipeline?order=${orderId}`}>Открыть заказ в воронке</Button>}
        <TextField select label="Ответственный за звонок / перезвон" value={userId} onChange={e=>setUserId(Number(e.target.value))}><MenuItem value={0}>Не назначен</MenuItem>{users.data?.map(u=><MenuItem key={u.id} value={u.id}>{u.name}</MenuItem>)}</TextField>
        <TextField label="Результат разговора / комментарий" multiline value={note} onChange={e=>setNote(e.target.value)} inputProps={{maxLength:2000}}/>
        {data.call.callbackDueAt && <><Typography>Перезвонить до {date(data.call.callbackDueAt)}</Typography><FormControlLabel label="Перезвон выполнен, результат записан" control={<Checkbox checked={done} disabled={!!data.call.callbackCompletedAt} onChange={e=>setDone(e.target.checked)}/>}/></>}
        <Button variant="contained" disabled={state.isLoading} onClick={()=>void save({id:data.call.id,orderId:orderId || null,userId:userId || null,note,callbackCompleted:done,version:data.call.version})}>Сохранить результат</Button>
    </Stack>;
}
export default function TelephonyPage() {
    const {isCompanyAdmin,isSuperAdmin} = useAuth(); const manager = isCompanyAdmin || isSuperAdmin;
    const [params,setParams] = useSearchParams(); const selected = params.get('call'); const calls = useCallsQuery(undefined,{pollingInterval:3000});
    const detail = useCallQuery(selected || '',{skip:!selected,pollingInterval:3000}); const settings = useTelephonySettingsQuery(undefined,{skip:!manager}); const users = useOperationsUsersQuery();
    const [editing,setEditing] = useState<(TelephonySettings & {secret:string})|null>(null); const [save,state] = useSaveTelephonyMutation(); const [callbacksOnly,setCallbacksOnly] = useState(false);
    const filtered = calls.data?.filter(c=>!callbacksOnly || (c.callbackDueAt && !c.callbackCompletedAt)) || [];
    const commit = async ()=>{if (!editing) return;try{await save(editing).unwrap();setEditing(null);}catch{/* Server error is shown below. */}};
    return <MainDiv><PageHeader><PageTitle>Телефония</PageTitle><Button component={Link} to="/orderPipeline">Воронка заказов</Button>{manager && <Button disabled={!settings.data} onClick={()=>settings.data && setEditing({...settings.data,secret:''})}>Подключение АТС</Button>}</PageHeader>
        <ErrorBox error={calls.error || settings.error || users.error} retry={()=>void calls.refetch()}/>
        {manager && settings.data && !settings.data.enabled && <Alert severity="info">Подключите АТС в настройках. После подключения новые звонки будут определяться по номеру клиента.</Alert>}
        <Surface><FormControlLabel label="Нужен перезвон" control={<Checkbox checked={callbacksOnly} onChange={e=>setCallbacksOnly(e.target.checked)}/>}/>{calls.isLoading && <Typography>Загрузка звонков…</Typography>}{!calls.isLoading && filtered.length===0 && <Typography>Звонков по этим условиям пока нет.</Typography>}<Box sx={{overflowX:'auto'}}><Table><TableHead><TableRow>{['Время','Номер','Направление','Статус','Заказ','Ответственный','Перезвон'].map(label=><TableCell key={label}>{label}</TableCell>)}</TableRow></TableHead><TableBody>{filtered.map(c=><TableRow key={c.id}><TableCell>{date(c.startedAt)}</TableCell><TableCell><Button onClick={()=>setParams({call:c.id})}>+{c.phone}</Button></TableCell><TableCell>{c.direction==='inbound'?'Входящий':'Исходящий'}</TableCell><TableCell><Chip color={c.state==='ringing'?'success':c.state==='missed'?'warning':'default'} label={states[c.state] || c.state}/></TableCell><TableCell>{c.orderId ? <Button component={Link} to={`/orderPipeline?order=${c.orderId}`}>№{c.orderId}</Button> : 'Уточнить'}</TableCell><TableCell>{users.data?.find(u=>u.id===c.assignedUserId)?.name || 'Не назначен'}</TableCell><TableCell>{c.callbackCompletedAt ? 'Выполнен' : c.callbackDueAt ? <Typography color={new Date(c.callbackDueAt)<new Date()?'error':'text.primary'}>{date(c.callbackDueAt)}</Typography> : '—'}</TableCell></TableRow>)}</TableBody></Table></Box><Typography variant="caption">Последние 200 звонков. Входящие события обновляются каждые 3 секунды.</Typography></Surface>
        <Dialog open={!!selected} onClose={()=>setParams({})} maxWidth="sm" fullWidth><DialogTitle>Карточка звонка</DialogTitle><DialogContent><ErrorBox error={detail.error} retry={()=>void detail.refetch()}/>{detail.isLoading && <Typography>Определяем клиента…</Typography>}{detail.data && <CallEditor key={`${detail.data.call.id}-${detail.data.call.version}`} data={detail.data}/>}</DialogContent><DialogActions><Button onClick={()=>setParams({})}>Закрыть</Button></DialogActions></Dialog>
        <Dialog open={!!editing} onClose={()=>setEditing(null)} maxWidth="sm" fullWidth><DialogTitle>Подключение телефонии</DialogTitle><DialogContent><Stack spacing={2} sx={{pt:1}}><ErrorBox error={state.error}/>{editing && <><FormControlLabel label="Принимать события звонков" control={<Checkbox checked={editing.enabled} onChange={e=>setEditing({...editing,enabled:e.target.checked})}/>}/><TextField select label="Тип АТС" value={editing.provider} onChange={e=>setEditing({...editing,provider:e.target.value})}><MenuItem value="asterisk">Asterisk / FreePBX</MenuItem><MenuItem value="generic">Другой оператор через адаптер</MenuItem></TextField><TextField type="password" autoComplete="new-password" label="Секрет интеграции" value={editing.secret} onChange={e=>setEditing({...editing,secret:e.target.value})} helperText={editing.hasSecret?'Секрет сохранён. Пустое поле сохраняет текущий секрет.':'От 32 символов. Этот же секрет задаётся в адаптере АТС.'}/><TextField type="number" label="Срок перезвона, минут" value={editing.callbackMinutes} onChange={e=>setEditing({...editing,callbackMinutes:Number(e.target.value)})} inputProps={{min:1,max:1440}}/><UserPicker users={users.data || []} ids={editing.recipientUserIds} label="Операторы: кому сообщать о звонках" onChange={ids=>setEditing({...editing,recipientUserIds:ids})}/><Typography color="text.secondary">Ответственные по найденным заказам также получают уведомления. Секрет вводится один раз и не отображается после сохранения.</Typography></>}</Stack></DialogContent><DialogActions><Button onClick={()=>setEditing(null)}>Отмена</Button><Button disabled={state.isLoading} onClick={()=>void commit()}>Сохранить</Button></DialogActions></Dialog>
    </MainDiv>;
}
